// Custom HUD (RP/ui/hud_screen.json): stackable widgets in the top right corner (the win counters and
// anything else), toast notifications under them, and the big centred titles. The widgets are the
// same design as Horrific Housing's (which was itself ported from this HUD).
//
// Everything travels through the vanilla title channel as ONE fixed-width string per player. JSON UI
// can only cut that string by byte position, so every field below has a fixed byte width that must
// match RP/ui/hud_screen.json (generated by tools/build_hud.mjs, which reads HUD_LAYOUT from this file).
//
// Because the title channel carries HUD data, do NOT use /title for visible titles anymore.
// Use instead (from an mcfunction, run as the player):
//   /scriptevent brr:hud title <text>        big title (shows the pending subtitle too)
//   /scriptevent brr:hud subtitle <text>     subtitle for the next/current title
//   /scriptevent brr:hud times <in> <stay> <out>   title timings in ticks (like /title times)
//   /scriptevent brr:hud toast <icon> <heading>|<subline>   icon: door | water | info
//   /scriptevent brr:hud widget <key> <style> <text>   show/update this player's own widget (style: see WIDGET_STYLES)
//   /scriptevent brr:hud unwidget <key>      remove it
//   /scriptevent brr:hud clear               remove the title, toasts and this player's own widgets
// e.g.  execute as @a run scriptevent brr:hud title §5§lEXTREME MODE
//
// Widgets flow in rows from the top right corner. A row is "full" by an estimate of the widgets'
// widths (ROW_BUDGET), since JSON UI can't measure the screen; the next widget starts a new row
// underneath. Within a row they read left to right in order. The toast sits under the last row.

import { system, world } from "@minecraft/server";

// ---- payload layout (byte offsets) -- read by tools/build_hud.mjs
export const HUD_LAYOUT = {
	marker: "FE:", //                 [0, 3)
	titleFrame: 3, //                 [3, 4)  '-' hidden, else one of TITLE_STEPS
	title: { start: 4, width: 60 }, // [4, 64)
	subtitle: { start: 64, width: 60 }, // [64, 124)
	toastFrame: 124, //               [124, 125) '-' hidden, else one of TOAST_FRAMES
	toastIcon: 125, //                [125, 126) one of TOAST_ICONS
	toastRow: 126, //                 [126, 127) how many widget rows are above the toast: one of TOAST_ROWS
	toastHeading: { start: 127, width: 48 }, // [127, 175)
	toastSubline: { start: 175, width: 48 }, // [175, 223)
	// rows x perRow widget slots, each one style byte (EMPTY_STYLE = empty) + text bytes
	widgets: { start: 223, rows: 3, perRow: 4, styleWidth: 1, textWidth: 40 }, // [223, 715)
	length: 715,
};
/**
 * Style byte of an empty widget slot. A letter, so the UI can hide empty slots with one comparison,
 * "not (style = 'z')". In game, a condition chaining 3+ checks ("a or b or c...", "a and b and c") is evaluated
 * wrongly, so every UI condition must be one comparison or two nested in brackets.
 */
export const EMPTY_STYLE = "z";
/**
 * Fade steps, faintest first. Letters, never digits: JSON UI turns a digit cut from the string into a
 * number, which never equals the text it's compared with (Horrific Housing's title never showed until
 * its steps were letters).
 */
export const TITLE_STEPS = "abcd";
export const TOAST_FRAMES = ["a", "b", "c", "d", "e", "f"]; // a = off screen ... f = resting position
export const TOAST_ICONS = { door: "d", water: "w", info: "i" };
/** Index = number of widget rows above the toast. */
export const TOAST_ROWS = "abcd";
/** Widget looks: background + icon from RP/textures/ui/fe_hud (see WIDGET_LOOKS in tools/build_hud.mjs). */
export const WIDGET_STYLES = { easy: "e", medium: "m", hard: "h", extreme: "x", endless: "n", plain: "p" };

// Estimated widths in GUI pixels for row wrapping; must match the LOOK in tools/build_hud.mjs.
const WIDGET_SCALE = 1.2;
/** Minecraft's font: most characters take 6 pixels (5 and a gap); these take less (or more). */
const CHAR_WIDTHS = { i: 2, l: 3, "!": 2, ":": 2, ";": 2, ",": 2, ".": 2, "'": 2, "|": 2, "`": 3, t: 4, I: 4, " ": 4, "[": 4, "]": 4, "(": 4, ")": 4, "{": 4, "}": 4, '"': 4, "*": 4, f: 5, k: 5, "<": 5, ">": 5, "@": 7, "~": 7 };
const CHAR_WIDTH = 6;
const GLYPH_WIDTH = 9;
const WIDGET_PADDING = 6 * 2 + 3 + 16 + 3; // inside the background, gap to the next widget, icon, gap after the icon
/** How wide a row of widgets may get before the next one wraps underneath. */
const ROW_BUDGET = 400;

const REFRESH_TICKS = 4;
const DEFAULT_TIMES = { fadeIn: 20, stay: 80, fadeOut: 20 };
const TOAST_STAY = 70; // ticks the toast rests on screen
const PAD = "§r"; // invisible, zero width: used to pad text fields so labels size to the real text

/**
 * A widget every player sees while `text` returns something (the win counters...).
 * @typedef {{ order: number, style: keyof typeof WIDGET_STYLES, text: (player: import("@minecraft/server").Player) => string | undefined }} WidgetDefinition
 */
/** @type {Map<string, WidgetDefinition>} */
const definitions = new Map();

/** player id -> state */
const players = new Map();
let added = 0;

function stateOf(player) {
	let state = players.get(player.id);
	if (!state) {
		state = { times: { ...DEFAULT_TIMES }, title: null, pendingSubtitle: "", toasts: [], toast: null, widgets: new Map(), lastPayload: "", lastSent: -Infinity };
		players.set(player.id, state);
	}
	return state;
}

// ---- byte-exact padding
function byteLength(text) {
	let length = 0;
	for (const ch of text) {
		const c = ch.codePointAt(0);
		length += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4;
	}
	return length;
}

function truncate(text, width) {
	let out = "";
	let length = 0;
	for (const ch of text) {
		const size = byteLength(ch);
		if (length + size > width) break;
		out += ch;
		length += size;
	}
	return out;
}

// Pads with invisible §r codes (3 bytes each), then 0-2 spaces for the remainder.
// centered: the leftover spaces are split around the text so centred labels stay centred.
export function padText(text, width, centered = false) {
	const body = truncate(String(text ?? ""), width);
	let rest = width - byteLength(body);
	const pads = Math.floor(rest / 3);
	rest -= pads * 3;
	const before = centered && body ? Math.floor(rest / 2) : 0;
	return " ".repeat(before) + body + PAD.repeat(pads) + " ".repeat(rest - before);
}

// A field a label shows: always starts with §r, without which Bedrock may not render it (a label that
// is only digits and spaces doesn't show at all).
export function labelText(text, width, centered = false) {
	return PAD + padText(text, width - byteLength(PAD), centered);
}

// ---- public API (also used by the room engine)
export function setTitleTimes(player, fadeIn, stay, fadeOut) {
	stateOf(player).times = { fadeIn: Math.max(0, fadeIn), stay: Math.max(0, stay), fadeOut: Math.max(0, fadeOut) };
}

export function showTitle(player, title, subtitle) {
	const state = stateOf(player);
	const sub = subtitle ?? state.pendingSubtitle;
	state.pendingSubtitle = "";
	state.title = { text: title ?? "", subtitle: sub ?? "", start: system.currentTick, ...state.times };
}

export function setSubtitle(player, subtitle) {
	const state = stateOf(player);
	if (state.title) state.title.subtitle = subtitle;
	else state.pendingSubtitle = subtitle;
}

// icon: "door" | "water" | "info"
export function showToast(player, icon, heading, subline = "") {
	stateOf(player).toasts.push({ icon: TOAST_ICONS[icon] ?? TOAST_ICONS.info, heading, subline });
}

/** Registers a widget for everyone. Lower `order` comes first; players' own widgets (setWidget) come after these. */
export function defineWidget(key, definition) {
	definitions.set(key, definition);
}

/** Shows or updates one player's own widget (a timer...). It stays until removeWidget. */
export function setWidget(player, key, style, text) {
	const widgets = stateOf(player).widgets;
	widgets.set(key, { style: WIDGET_STYLES[style] ? style : "plain", text, added: widgets.get(key)?.added ?? added++ });
}

export function removeWidget(player, key) {
	stateOf(player).widgets.delete(key);
}

export function clearHud(player) {
	const state = stateOf(player);
	state.title = null;
	state.toasts = [];
	state.toast = null;
	state.widgets.clear();
}

// ---- widgets
/** Rough on-screen width of a widget, for wrapping rows. */
export function widgetWidth(text) {
	let width = 0;
	for (const ch of text.replace(/§./g, "")) width += ch.codePointAt(0) >= 0xe000 ? GLYPH_WIDTH : (CHAR_WIDTHS[ch] ?? CHAR_WIDTH);
	return width * WIDGET_SCALE + WIDGET_PADDING;
}

/** Everything this player should see, in order: defined widgets by order, then their own by age. */
function widgetsFor(player, state) {
	const list = [];
	for (const definition of [...definitions.values()].sort((a, b) => a.order - b.order)) {
		let text;
		try {
			text = definition.text(player);
		} catch {
			text = undefined;
		}
		if (text) list.push({ style: definition.style, text });
	}
	for (const widget of [...state.widgets.values()].sort((a, b) => a.added - b.added)) list.push(widget);
	return list;
}

/** Splits widgets into rows by ROW_BUDGET; at most HUD_LAYOUT.widgets.rows rows of perRow. */
export function layoutWidgets(widgets) {
	const { rows, perRow } = HUD_LAYOUT.widgets;
	const grid = [[]];
	let used = 0;
	for (const widget of widgets) {
		const width = widgetWidth(widget.text);
		let row = grid[grid.length - 1];
		if (row.length > 0 && (row.length >= perRow || used + width > ROW_BUDGET)) {
			if (grid.length >= rows) break;
			grid.push((row = []));
			used = 0;
		}
		row.push(widget);
		used += width;
	}
	return grid.filter((row) => row.length);
}

// ---- frame computation
function titleFrame(state, now) {
	const t = state.title;
	if (!t) return "-";
	const age = now - t.start;
	const total = t.fadeIn + t.stay + t.fadeOut;
	if (age >= total) {
		state.title = null;
		return "-";
	}
	let level = 1;
	if (age < t.fadeIn) level = (age + 1) / (t.fadeIn + 1);
	else if (age >= t.fadeIn + t.stay) level = (total - age) / (t.fadeOut + 1);
	const steps = TITLE_STEPS.length;
	return TITLE_STEPS[Math.max(1, Math.min(steps, Math.ceil(level * steps))) - 1];
}

function toastFrame(state, now) {
	if (!state.toast && state.toasts.length) state.toast = { ...state.toasts.shift(), start: now };
	const toast = state.toast;
	if (!toast) return "-";
	const steps = TOAST_FRAMES.length - 1; // frames b..f slide in, then back out
	const age = now - toast.start;
	if (age < steps) return TOAST_FRAMES[age + 1];
	if (age < steps + TOAST_STAY) return TOAST_FRAMES[steps];
	const out = age - steps - TOAST_STAY;
	if (out < steps) return TOAST_FRAMES[steps - 1 - out];
	state.toast = null;
	return toastFrame(state, now);
}

/** @param widgets optional list to show instead of the player's (previews) */
export function buildPayload(player, state, now, widgets = widgetsFor(player, state)) {
	const L = HUD_LAYOUT;
	const W = L.widgets;
	const tf = titleFrame(state, now);
	const t = state.title;
	const sf = toastFrame(state, now);
	const toast = state.toast;
	const grid = layoutWidgets(widgets);

	// Slot 0 of a row is the one in the corner, so a row's widgets go in reversed: they then read left to right.
	let slots = "";
	for (let row = 0; row < W.rows; row++) {
		const list = grid[row] ?? [];
		for (let slot = 0; slot < W.perRow; slot++) {
			const widget = list[list.length - 1 - slot];
			slots += widget ? WIDGET_STYLES[widget.style] + labelText(widget.text, W.textWidth) : EMPTY_STYLE + labelText("", W.textWidth);
		}
	}

	return L.marker
		+ tf
		+ labelText(t?.text, L.title.width, true)
		+ labelText(t?.subtitle, L.subtitle.width, true)
		+ sf
		+ (toast?.icon ?? "-")
		+ TOAST_ROWS[Math.min(grid.length, TOAST_ROWS.length - 1)]
		+ labelText(toast?.heading, L.toastHeading.width)
		+ labelText(toast?.subline, L.toastSubline.width)
		+ slots;
}

function handleScriptEvent(event) {
	if (event.id !== "brr:hud") return;
	const player = event.sourceEntity;
	if (player?.typeId !== "minecraft:player") {
		console.warn("[Flood Escape] brr:hud must run as a player (execute as @a run scriptevent brr:hud ...)");
		return;
	}
	const message = event.message ?? "";
	const space = message.indexOf(" ");
	const action = (space < 0 ? message : message.slice(0, space)).toLowerCase();
	const rest = space < 0 ? "" : message.slice(space + 1);
	if (action === "title") showTitle(player, rest);
	else if (action === "subtitle") setSubtitle(player, rest);
	else if (action === "times") {
		const [fadeIn, stay, fadeOut] = rest.split(/\s+/).map(Number);
		setTitleTimes(player, fadeIn || 0, stay || 0, fadeOut || 0);
	} else if (action === "toast") {
		const firstSpace = rest.indexOf(" ");
		const icon = firstSpace < 0 ? rest : rest.slice(0, firstSpace);
		const [heading, subline] = (firstSpace < 0 ? "" : rest.slice(firstSpace + 1)).split("|");
		showToast(player, icon, heading ?? "", subline ?? "");
	} else if (action === "widget") {
		const [key, style, ...text] = rest.split(" ");
		if (key && style) setWidget(player, key, style, text.join(" "));
	} else if (action === "unwidget") removeWidget(player, rest.trim());
	else if (action === "clear") clearHud(player);
	else console.warn(`[Flood Escape] brr:hud: unknown action "${action}"`);
}

export function registerHudSystems() {
	system.afterEvents.scriptEventReceive.subscribe(handleScriptEvent);
	world.afterEvents.playerLeave.subscribe(({ playerId }) => players.delete(playerId));

	system.runInterval(() => {
		const now = system.currentTick;
		for (const player of world.getAllPlayers()) {
			const state = stateOf(player);
			let payload;
			try {
				payload = buildPayload(player, state, now);
			} catch (error) {
				console.warn(`[Flood Escape] HUD payload failed: ${error}`);
				continue;
			}
			// Send when something changed (a fade step, a score), and every few ticks anyway so the HUD never times out.
			if (payload === state.lastPayload && now - state.lastSent < REFRESH_TICKS) continue;
			try {
				player.onScreenDisplay.setTitle(payload, { fadeInDuration: 0, stayDuration: REFRESH_TICKS * 3, fadeOutDuration: 0 });
				state.lastPayload = payload;
				state.lastSent = now;
			} catch {
				// player not ready yet
			}
		}
	}, 1);
}
